// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY channels (PostgreSQL / Vitess) {
  [PK ] channel_id             UUID
        type                   ENUM('DIRECT','GROUP')
        name                   VARCHAR(128)
        member_count           INT
        created_at             TIMESTAMPTZ
}

ENTITY channel_members (PostgreSQL / Vitess) {
  [PK ] channel_id             UUID (Composite PK)
  [PK ] user_id                UUID (Composite PK)
        last_ack_msg_id        BIGINT (Snowflake)
        role                   ENUM('ADMIN','MEMBER')
        joined_at              TIMESTAMPTZ
}

ENTITY chat_messages (Cassandra / ScyllaDB) {
  [PK ] channel_id             UUID (Partition Key)
  [PK ] message_id             BIGINT (Clustering DESC)
  [FK ] sender_id              UUID
        content                TEXT
        created_at             TIMESTAMP
}

// Relationships: channels --(1 : N (membership))--> channel_members --(1 : N (ordered messages))--> chat_messages
